// Imagenes de marca incrustadas como data URI en base64.
// Se generaron desde los assets reales de Look Makers (logo, foto de la
// lashista y la imagen hero de pestanas) para poder subirlas al
// repositorio de forma segura via la API de contenidos de GitHub, que
// solo admite texto. Si mas adelante prefieres servirlas como archivos
// estaticos normales, ya estan tambien en /public/images/*.webp: basta
// con cambiar estas constantes por rutas ("/images/logo.webp", etc.).

export const LOGO_DATA_URI = "data:image/webp;base64,";
export const EYE_DATA_URI = "data:image/webp;base64,";
export const LASHISTA_DATA_URI = "data:image/webp;base64,";

// Imagen limpia (sin logo ni texto) para la portada de bienvenida de pantalla completa.
export const EYE_PORTADA_DATA_URI = "data:image/webp;base64,";
